@Component("labResult-handler")
@ProcessingGroup("labResult-processing-group")
public class LabResultEventHandler {
	
	// core constructor
	LabResultEventHandler(EntityManager entityManager) {
        this.entityManager = entityManager;
    }	
	
    /*
     * @param	event CreateLabResultEvent
     */
    @EventHandler
    public void handle( CreateLabResultEvent event) {
        entityManager.persist(new LabResult(event.getLabResultId(), event.getResultCode(), event.getIssuedDate(), event.getLaboratoryOrder(), event.getObservations(), event.getLaboratory(), event.getStatus()));
    }

    /*
     * @param	event UpdateLabResultEvent
     */
    @EventHandler
    public LabResult handle( UpdateLabResultEvent event) {
    	entityManager.merge(new LabResult(event.getLabResultId(), event.getResultCode(), event.getIssuedDate(), event.getLaboratoryOrder(), event.getObservations(), event.getLaboratory(), event.getStatus()));
    }
    
    /*
     * @param	event DeleteLabResultEvent
     */
    @EventHandler
    public void on( DeleteLabResultEvent event) {
    	LabResult entity = new LabResult();
   
    	// ------------------------------------------
    	// apply the LabResultId
    	// ------------------------------------------
    	entity.setLabResultId( event.getLabResultId() );
    	
    	// ------------------------------------------
    	// add to an Iterable and delete
    	// ------------------------------------------
    	entityManager.remove( entity );
    }    
    
    // attributes
	private final LabResultRepository labResultEntityRepository;
    private static final Logger LOGGER 			= Logger.getLogger(LabResultEventHandler.class.getName());

}
